using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class QualityTests
{
    private static TracerProvider? _telemetry;
    private static ReportingConfiguration? _reporting;
    private static IChatClient? _chatClient;

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        _telemetry = EvalConfig.BuildTelemetry();

        // The chat client under evaluation. Replace endpoint/key as needed.
        _chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
                ?? "https://localhost"),
            new System.ClientModel.ApiKeyCredential(
                Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key"))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        _reporting = EvalConfig.CreateReportingConfig(_chatClient, scenarioName: "quality");
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        _telemetry?.Dispose();
    }

    [TestMethod]
    [DataRow("What is dependency injection?", "Dependency injection is a design pattern")]
    [DataRow("Explain async/await in C#", "async and await are keywords")]
    public async Task Response_MeetsQualityThresholds(string prompt, string expectedSubstring)
    {
        await using var scenario = await _reporting!.CreateScenarioRunAsync(
            $"quality_{prompt[..20].Replace(" ", "_")}");

        var messages = new List<ChatMessage> { new(ChatRole.User, prompt) };
        var response = await _chatClient!.GetResponseAsync(messages);

        // Record the turn for evaluation
        scenario.Record(
            new ChatTurn(messages, response));

        var results = await scenario.EvaluateAsync();

        foreach (var result in results)
        {
            Assert.IsFalse(
                result.Value.Rating?.Value < 3,
                $"Evaluator '{result.Key}' scored below threshold: {result.Value.Rating}");
        }
    }
}

