using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same prompts against two model configurations and stores
/// results side-by-side in the reporting storage for diffing.
/// </summary>
[TestClass]
public sealed class CompareTests
{
    private static TracerProvider? _telemetry;

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        _telemetry = EvalConfig.BuildTelemetry();
    }

    [ClassCleanup]
    public static void Cleanup()
    {
        _telemetry?.Dispose();
    }

    [TestMethod]
    [DataRow("Summarize the benefits of microservices architecture.")]
    [DataRow("Write a haiku about cloud computing.")]
    public async Task Compare_BaselineVsCandidate(string prompt)
    {
        var endpoint = new Uri(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT") ?? "https://localhost");
        var key = new System.ClientModel.ApiKeyCredential(
            Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? "test-key");

        var azClient = new Azure.AI.OpenAI.AzureOpenAIClient(endpoint, key);

        // Baseline model
        IChatClient baseline = azClient
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();

        // Candidate model (swap deployment name to compare)
        IChatClient candidate = azClient
            .GetChatClient(
                Environment.GetEnvironmentVariable("CANDIDATE_MODEL") ?? "gpt-4o")
            .AsIChatClient();

        var reportingBaseline = EvalConfig.CreateReportingConfig(baseline, "compare-baseline");
        var reportingCandidate = EvalConfig.CreateReportingConfig(candidate, "compare-candidate");

        var messages = new List<ChatMessage> { new(ChatRole.User, prompt) };
        var slug = prompt[..Math.Min(30, prompt.Length)].Replace(" ", "_");

        // Run baseline
        await using (var scenario = await reportingBaseline.CreateScenarioRunAsync($"compare_{slug}"))
        {
            var response = await baseline.GetResponseAsync(messages);
            scenario.Record(new ChatTurn(messages, response));
            await scenario.EvaluateAsync();
        }

        // Run candidate
        await using (var scenario = await reportingCandidate.CreateScenarioRunAsync($"compare_{slug}"))
        {
            var response = await candidate.GetResponseAsync(messages);
            scenario.Record(new ChatTurn(messages, response));
            await scenario.EvaluateAsync();
        }

        // Results are persisted in storage; use `dotnet eval report` or inspect
        // the results directory to compare scores side-by-side.
    }
}

